// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /quizzes/generate').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Test oluşturma isteğini doğrular.
const b = $('POST /quizzes/generate').first().json.body || {};
const s = (v) => (v === null || v === undefined ? '' : String(v).trim());
const count = s(b.question_count) === '' ? 5 : Number(b.question_count);
const difficulty = s(b.difficulty) || 'medium';
const fail = (message) => [{ json: { valid: false, response: { ok: false, error: { code: 'VALIDATION_ERROR', message } } } }];
if (!Number.isInteger(count) || count < 5 || count > 10) return fail('Soru sayısı 5-10 arasında olmalıdır.');
if (!['easy', 'medium', 'hard'].includes(difficulty)) return fail("Zorluk 'easy', 'medium' veya 'hard' olmalıdır.");
return [{
  json: {
    valid: true,
    user_id: $('Test: oturum').first().json.user_id,
    note_id: s(b.note_id) || '-',
    count,
    difficulty,
    model: s(b.model) || null,
  },
}];

// Test üretimi için Ollama isteğini hazırlar. Şema, case dokümanındaki yapı + "topic".
const n = $('Test: not').first().json;
const r = $('Test: istek').first().json;
const level = {
  easy: 'kolay (temel tanımlar ve kavramlar)',
  medium: 'orta (kavramları anlama ve karşılaştırma)',
  hard: 'zor (uygulama, analiz ve çıkarım)',
}[r.difficulty];
// Model birkaç fazla (yedek) soru üretir; kurallara uymayan sorular kodda elenir.
const ask = r.count + 2;
const schema = {
  type: 'object',
  properties: {
    questions: {
      type: 'array', minItems: ask, maxItems: ask,
      items: {
        type: 'object',
        properties: {
          question: { type: 'string' },
          options: { type: 'array', items: { type: 'string' }, minItems: 4, maxItems: 4 },
          correct_answer: { type: 'string' },
          explanation: { type: 'string' },
          topic: { type: 'string' },
        },
        required: ['question', 'options', 'correct_answer', 'explanation', 'topic'],
      },
    },
  },
  required: ['questions'],
};
const system = [
  'Sen üniversite öğrencileri için ders notlarından çoktan seçmeli test hazırlayan bir öğretim asistanısın.',
  'KURALLAR:',
  '1. YALNIZCA Türkçe yaz. Çince, Japonca, Korece veya Kiril alfabesinden tek bir karakter bile kullanma.',
  `2. Tam olarak ${ask} soru üret. Zorluk düzeyi: ${level}.`,
  '3. Sorular YALNIZCA verilen ders notundaki bilgilere dayansın.',
  '4. Her sorunun tam 4 farklı seçeneği olsun ve yalnızca biri doğru olsun. Seçeneklerin başına "A)" gibi harf koyma.',
  '5. "correct_answer", doğru seçeneğin metniyle BİREBİR aynı olsun.',
  '6. "explanation", doğru cevabın neden doğru olduğunu 1-2 cümleyle açıklasın.',
  '7. "topic", sorunun ölçtüğü konuyu 1-4 kelimeyle belirtsin (ör. "Widget türleri").',
  '8. Aynı soruyu tekrarlama; "Hepsi" veya "Hiçbiri" seçeneğini kullanma.',
  '9. Doğru cevabı soru metninin içinde verme; yanlış seçenekler de akla yatkın olsun.',
  '10. Soruları dil bilgisi açısından düzgün, açık ve tek anlamlı yaz.',
].join('\n');
// Otomatik model seçimi: formül yoğun / sayısal notlar → akıl yürütme modeli, diğerleri → Türkçe anlatım modeli
const low = n.content.toLocaleLowerCase('tr');
const symbolRatio = (n.content.match(/[=^+*/×÷√∫<>]/g) || []).length / Math.max(n.content.length, 1);
const hits = ['türev', 'integral', 'limit', 'denklem', 'matris', 'olasılık', 'fonksiyon', 'formül', 'algoritma', 'kod']
  .filter((w) => low.includes(w)).length;
const route = symbolRatio > 0.01 || hits >= 2 ? 'reasoning' : 'text';

return [{
  json: {
    route,
    body: {
      model: r.model,
      stream: false,
      format: schema,
      options: { temperature: 0.4, num_ctx: 8192 },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `Ders notu başlığı: ${n.title}\n\nDers notu:\n${n.content}` },
      ],
    },
  },
}];

// Test belgesini (doğru cevaplarla) ve istemci yanıtını (doğru cevap ve açıklama OLMADAN) hazırlar.
const crypto = require('crypto');
const n = $('Test: not').first().json;
const req = $('Test: istek').first().json;
const v = $input.first().json;
const quiz = {
  id: crypto.randomUUID(),
  user_id: req.user_id,
  note_id: n.id,
  course_id: n.course_id,
  title: `${n.title} — Test`,
  model: v.model || 'bilinmiyor',
  difficulty: req.difficulty,
  questions: v.questions.map((q, i) => ({ id: crypto.randomUUID(), position: i + 1, ...q })),
  created_at: new Date().toISOString(),
};
const response = {
  ok: true,
  data: {
    quiz_id: quiz.id, title: quiz.title, model: quiz.model, difficulty: quiz.difficulty,
    questions: quiz.questions.map((q) => ({
      id: q.id, position: q.position, question: q.question, options: q.options, topic: q.topic,
    })),
  },
};
return [{ json: { ...quiz, response } }];

// Model çıktısını case dokümanındaki şemaya göre doğrular, correct_answer'ı correct_index'e çevirir
// ve şıkları karıştırır (modeller doğru cevabı hep aynı sıraya koyma eğilimindedir).
const crypto = require('crypto');
const r = $input.first().json;
const req = $('Test: istek').first().json;
const raw = (r.message && typeof r.message.content === 'string') ? r.message.content : '';
const FOREIGN = /[぀-ヿ㐀-䶿一-鿿豈-﫿가-힯Ѐ-ӿ]/;
const clean = (v) => String(v ?? '').trim();
const noLetter = (v) => clean(v).replace(/^[A-Da-d][).:-]\s+/, '');
const tr = (v) => v.toLocaleLowerCase('tr');

const check = () => {
  let j;
  try { j = JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')); }
  catch (e) { return { problem: 'geçersiz JSON' }; }
  const qs = j && Array.isArray(j.questions) ? j.questions : null;
  if (!qs) return { problem: '"questions" dizisi yok' };
  // Her soru tek tek denetlenir; kurala uymayan soru elenir (model yedek sorular üretir).
  // İstenen sayıda geçerli soru kalırsa test kabul edilir.
  const out = [];
  const rejected = [];
  const seen = new Set();
  for (const [i, q] of qs.entries()) {
    if (out.length >= req.count) break;
    const no = i + 1;
    const question = clean(q && q.question);
    const options = Array.isArray(q && q.options) ? q.options.map(noLetter) : [];
    const answer = noLetter(q && q.correct_answer);
    const explanation = clean(q && q.explanation);
    const topic = clean(q && q.topic).slice(0, 100);
    const why = (() => {
      if (!question) return 'boş soru';
      if (options.length !== 4 || options.some((o) => !o)) return '4 dolu seçenek yok';
      if (new Set(options.map(tr)).size !== 4) return 'tekrar eden seçenek';
      if (!explanation) return 'açıklama yok';
      if (!topic) return 'konu yok';
      if (seen.has(tr(question))) return 'tekrar eden soru';
      if (FOREIGN.test(question + options.join('') + explanation + topic)) return 'Türkçe dışı karakter';
      return null;
    })();
    let ci = options.indexOf(answer);
    if (ci < 0) ci = options.map(tr).indexOf(tr(answer));
    const problem = why || (ci < 0 ? 'doğru cevap seçeneklerde yok'
      : (options[ci].length >= 4 && tr(question).includes(tr(options[ci])) ? 'cevap soru metninde' : null));
    if (problem) { rejected.push(`${no}. soru: ${problem}`); continue; }
    seen.add(tr(question));
    out.push({ question, options, correct_index: ci, explanation, topic });
  }
  if (out.length < req.count) {
    return { problem: `${out.length} geçerli soru (${req.count} gerekli); elenen: ${rejected.join('; ') || 'yok'}` };
  }

  // Doğru cevap konumlarını DENGELİ dağıt: her 4 soruda A/B/C/D birer kez (sırası rastgele).
  // Böylece "doğru cevap hep A" gibi bir örüntü oluşamaz; yanlış şıklar da karıştırılır.
  const shuffle = (a) => { for (let k = a.length - 1; k > 0; k--) { const m = crypto.randomInt(k + 1); [a[k], a[m]] = [a[m], a[k]]; } return a; };
  let slots = [];
  while (slots.length < out.length) slots.push(...shuffle([0, 1, 2, 3]));
  slots = shuffle(slots.slice(0, out.length));
  out.forEach((q, i) => {
    const correct = q.options[q.correct_index];
    const others = shuffle(q.options.filter((_, k) => k !== q.correct_index));
    others.splice(slots[i], 0, correct);
    q.options = others;
    q.correct_index = slots[i];
  });
  return { questions: out };
};

const res = check();
return [{
  json: {
    valid: !res.problem, problem: res.problem || null, attempt: $runIndex + 1,
    questions: res.questions || null, model: r.model || null,
  },
}];
